def next_smallest_palindrome(n: int) -> int:
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    def create_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    s = str(n)
    length = len(s)
    odd_length = (length % 2 != 0)

    # Start searching from n+1
    candidate = n + 1

    while True:
        s_cand = str(candidate)
        length_cand = len(s_cand)

        # If length changed (e.g. 999 -> 1000), recompute parameters
        if length_cand != length:
            length = length_cand
            odd_length = (length % 2 != 0)

        half_len = (length + 1) // 2
        left = s_cand[:half_len]

        pal = create_palindrome(left, odd_length)
        if pal >= candidate:
            if pal > n:
                return pal
            candidate = pal + 1
        else:
            # Increment left half and try again
            left_int = int(left) + 1
            left = str(left_int)
            # If length of left changed, handle overflow (e.g. 99+1=100)
            if len(left) > half_len:
                length += 1
                odd_length = (length % 2 != 0)
                half_len = (length + 1) // 2
                left = '1' + ('0' * (half_len - 1))
            pal = create_palindrome(left, odd_length)
            if pal > n:
                return pal
            candidate = pal + 1

