    # Split string into words and spaces (capture spaces so they are kept)
    parts = re.findall(r'\S+|\s+', s)
    result = []
    for part in parts:
        if part.isspace():
            # Keep spaces as is
            result.append(part)
        else:
            # Sort characters of the word (including punctuation attached)
            sorted_word = ''.join(sorted(part))
            result.append(sorted_word)
    return ''.join(result)

